#include<bits/stdc++.h>
using namespace std;int main(){map<int,set<int>> t; for(int n=1;n<=6;n++){vector<pair<int,int>> e;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)e.push_back({i,j});for(int a=0;a<(1<<e.size());a++){int R[6]={};for(unsigned k=0;k<e.size();k++){auto [i,j]=e[k];if(a>>k&1)swap(i,j);R[i]|=1<<j;}int h[64]={1},b[64][6]={};for(int s=1;s<(1<<n);s++)for(int x=s;x;x&=x-1){int i=__builtin_ctz(x),q=s^(1<<i);if(!q)b[s][i]=1;for(int w=q&R[i];w;w&=w-1)b[s][i]+=b[q][__builtin_ctz(w)];h[s]+=b[s][i];}int z=0,F=(1<<n)-1;for(int v=1;v<F;v++)z+=h[v]*h[F^v];t[z].insert(h[F]);}}for(auto&[z,h]:t)for(int x:h)if(h.count(x+2)&&h.count(x+4))cout<<z<<": "<<x<<","<<x+2<<","<<x+4<<" and next="<<h.count(x+6)<<"\n";}
